import unittest
from tools.kjv_archive import load_register, read


class SamuelFinalTests(unittest.TestCase):
    def test_speaker_shifts_historical_senses_and_source_quantities(self):
        old, _ = load_register('0.10-kjv.53')
        lang, manifest = load_register('0.10-kjv.54')
        self.assertEqual(old.lexicon, {k: lang.lexicon[k] for k in old.lexicon})
        for field in ('pairs', 'suffix', 'prefix', 'possessors', 'roman'):
            self.assertEqual(getattr(old, field), getattr(lang, field))
        cases = {c['id']: c for c in read(lang.folder / 'samuel2-final-cases.json')}
        self.assertEqual(115, len(cases))
        for case in cases.values():
            result = lang.compile(case['analysis'])
            self.assertEqual(case['expectedText'], result['text'])
            self.assertEqual(case['expectedGloss'], result['gloss'])
        checks = {'22-1': ['of all his/enemy:pl hand', 'of kjv_saul hand'], '22-2': ['my/rock', 'my/fortress', 'my/deliver:ag'], '22-3': ['in he i trust:fu', 'my/kjv_shield_armour', 'of my/salvation horn', 'from kjv_violence i:a thou save:pr'], '22-5': ['of death kjv_wave:pl', 'kjv_ungodly man:pl flood:pl'], '22-6': ['of kjv_hell sorrow:pl', 'before i come:pa'], '22-7': ['his/kjv_temple_sanctuary', 'into his/ear:pl my/cry enter:pa'], '22-8': ['of heaven kjv_foundation:pl', 'because angry he be:pa'], '22-9': ['his/kjv_nostril:pl smoke', 'his/mouth fire', 'kjv_charcoal:pl'], '22-11': ['upon kjv_cherub', 'he see:psv:pa'], '22-12': ['darkness:a kjv_pavilion:pl', 'dark water:pl'], '22-14': ['most high his/voice:a utter:pa'], '22-16': ['kjv_sea_channel:pl', 'kjv_foundation:pl kjv_uncover:psv:pa', 'his/kjv_nostril:pl breath kjv_blast'], '22-17': ['out of many water:pl i:a he draw:pa'], '22-19': ['before i they come:pa', 'my/support:ev'], '22-20': ['broad kjv_place_site', 'in i delight:a'], '22-21': ['my/kjv_righteousness', 'my/hand:pl kjv_cleanness'], '22-22': ['i keep:perf', 'i depart:perf not'], '22-24': ['my/kjv_iniquity self:a i keep:perf'], '22-26': ['merciful', 'kjv_uprightness:adj'], '22-27': ['kjv_froward person', 'kjv_unsavoury thou show:fu'], '22-28': ['kjv_afflict:psv people', 'proud person:pl', 'bring:pr:may down'], '22-29': ['my/lamp', 'light:caus:fu'], '22-30': ['through troop i run:perf', 'over wall i leap:perf'], '22-31': ['word test:psv:pr', 'kjv_shield_armour'], '22-32': ['except kjv_lord', 'ourone/god'], '22-34': ['female deer foot:pl'], '22-35': ['of steel bow', 'by my/arm:pl break:psv:pr'], '22-36': ['thy/gentleness i:a great make:perf'], '22-38': ['mypl/enemy:pl:a ipl pursue:perf', 'until they:a ipl consume:pp'], '22-39': ['under mypl/foot:pl'], '22-40': ['ipl:a thou kjv_gird:perf', 'under ipl'], '22-41': ['mypl/enemy:pl neck:pl', 'ipl destroy:pr:may'], '22-42': ['even to kjv_lord', 'he answer:pa not'], '22-43': ['dust', 'mud', 'ipl beat:pa', 'ipl stamp:pa'], '22-44': ['mypl/people', 'people whom i know:pa not ipl:a serve:fu'], '22-45': ['to ipl submit:fu'], '22-46': ['their/close:psv kjv_place_site:pl'], '22-48': ['ipl:a kjv_avenge:pr'], '22-49': ['i:a thou deliver:perf'], '22-50': ['among kjv_heathen', 'i give:fu', 'i sing:fu'], '22-51': ['of salvation kjv_tower', 'to his/seed forever'], '23-1': ['last word:pl', 'sweet kjv_psalm:ag'], '23-2': ['spirit by i speak:pa', 'his/word in my/tongue'], '23-3': ['kjv_right_conduct:adj', 'in of god fear'], '23-5': ['my/house so be:pr not', 'eternal kjv_covenant', 'it:a he grow:caus:pr not'], '23-6': ['as thorn:pl', 'hand:pl they take:psv:pr:can not'], '23-7': ['with iron', 'shield:psv:pr:must'], '23-8': ['kjv_tachmonite', 'kjv_adino kjv_eznite', 'eight+hundred', 'at one time'], '23-9': ['kjv_eleazar_dodo of kjv_dodo_ahohite', 'one of kjv_three'], '23-10': ['his/hand kjv_cling:pa', 'only to spoil:inf'], '23-11': ['kjv_shammah_agee of kjv_agee', 'kjv_lentil:pl'], '23-13': ['kjv_three of kjv_three+ten', 'kjv_adullam_city', 'kjv_encamp:pa'], '23-15': ['kjv_bethlehem kjv_well', 'give:opt', 'be:pr:excl'], '23-16': ['kjv_three mighty man:pl', 'drink:inf he will:pa not', 'to kjv_lord it:a pour:pa out'], '23-17': ['their/life:pl danger', 'blood this be:pr not'], '23-18': ['chief among kjv_three', 'kjv_three+hundred', 'name:a have:pa'], '23-19': ['to first kjv_three he reach:pa not'], '23-20': ['two lion like man:pl', 'kjv_pit', 'snow time lion:a'], '23-21': ['kjv_goodly man', 'with his/own kjv_spear'], '23-23': ['kjv_three+ten', 'first kjv_three', 'over his/guard'], '23-24': ['kjv_elhanan_dodo of kjv_dodo_bethlehem'], '23-25': ['kjv_shammah_harodite', 'kjv_elika'], '23-26': ['kjv_ira_ikkesh of kjv_ikkesh'], '23-27': ['kjv_abiezer_anethothite'], '23-28': ['kjv_zalmon_ahohite'], '23-29': ['kjv_baanah_netophah', 'kjv_ittai_ribai of kjv_ribai'], '23-30': ['kjv_benaiah_pirathonite'], '23-32': ['of of kjv_jashen son:pl kjv_jonathan_jashen'], '23-33': ['kjv_shammah_hararite', 'kjv_ahiam'], '23-34': ['kjv_eliphelet_ahasbai', 'kjv_eliam_ahithophel'], '23-36': ['kjv_igal_zobah of kjv_nathan_zobah'], '23-37': ['kjv_armour carry:ag', 'kjv_joab of kjv_zeruiah'], '23-38': ['kjv_ira_ithrite', 'kjv_gareb'], '23-39': ['kjv_uriah kjv_hittite', 'kjv_three+ten and seven'], '24-1': ['of kjv_lord anger', 'kjv_david:a he move:pa', 'kjv_number:imp'], '24-2': ['kjv_number:imp', 'i know:pr:may'], '24-3': ['hundred kjv_fold', 'add:opt'], '24-4': ['king word prevail:pa', 'kjv_number:inf'], '24-5': ['kjv_aroer kjv_encamp:pa', 'kjv_right_side'], '24-6': ['kjv_tahtimhodshi', 'kjv_danjaan'], '24-8': ['nine month:pl and two+ten day:pl'], '24-9': ['eight+hundred+thousand', 'five+hundred+thousand'], '24-10': ['heart he:a strike:pa', 'i sin:perf', 'i do:perf'], '24-11': ['kjv_gad_prophet', 'kjv_seer'], '24-12': ['kjv_three thing:pl:a ipl offer:pr', 'of they one', 'ipl do:pr:may'], '24-13': ['seven of kjv_famine year:pl', 'kjv_three month:pl', 'kjv_three day:pl kjv_pestilence', 'i return:fu'], '24-14': ['distress i be:pr', 'wesg fall:opt', 'i fall:opt not'], '24-15': ['appoint:psv time', 'seven+ten+thousand'], '24-16': ['kjv_lord repent:pa', 'enough it be:pr', 'thy/hand:a stop:imp', 'kjv_araunah'], '24-17': ['i sin:perf', 'these sheep what:a they do:perf', 'against my/father house'], '24-18': ['kjv_threshfloor', 'altar:a raise:imp'], '24-21': ['kjv_threshfloor:a buy:inf', 'plague stop:psv:pr:may'], '24-22': ['kjv_thresh:ev instrument:pl', 'for wood'], '24-23': ['as king to king kjv_araunah give:pa', 'accept:opt'], '24-24': ['at price', 'nothing cost:pr', 'five+ten kjv_shekel:pl of silver'], '24-25': ['peace kjv_offering:pl', 'plague stop:psv:pa']}
        for ref, parts in checks.items():
            for part in parts:
                self.assertIn(part, cases["2-samuel-" + ref]["analysis"])
        self.assertEqual('data/language/archaic-kjv-53', manifest['basePackage'])


if __name__ == '__main__':
    unittest.main()
